import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

import peggy from 'peggy';
import tspegjs from 'ts-pegjs';

const main = async (): Promise<void> => {
  const cwd = process.cwd();
  const grammarPath = resolve(cwd, 'src/edl/edl.peggy');
  const outPath = resolve(cwd, 'src/edl/parser.ts');

  const grammar = await readFile(grammarPath, 'utf8');

  const source = peggy.generate(grammar, {
    format: 'es',
    output: 'source',
    plugins: [tspegjs]
  }) as string;

  const banner =
    '/* This file is generated by scripts/generate-edl-parser.ts. Do not edit manually. */\n';
  const extra = '\nexport { parse as parseEDL };\n';

  await writeFile(outPath, banner + source + extra, 'utf8');
  // eslint-disable-next-line no-console
  console.log(`Generated: ${outPath}`);
};

try {
  await main();
} catch (error) {
  // eslint-disable-next-line no-console
  console.error(error);
  process.exit(1);
}
